'use client';
import {useEffect,useMemo,useState} from 'react';import VendorShell from '../../components/VendorShell';import {api,post,patch} from '../../lib/api';
const naira=(k:number)=>`₦${(Number(k||0)/100).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const blank={name:'',objective:'ORDERS',budget:'',startsAt:'',endsAt:'',outletId:'',productIds:[] as string[]};
function state(c:any){const now=Date.now();if(c.status==='PAUSED')return 'Paused';if(c.status==='ENDED')return 'Ended';if(new Date(c.startsAt).getTime()>now)return 'Scheduled';if(new Date(c.endsAt).getTime()<now)return 'Ended';if(c.status==='ACTIVE')return 'Active';return 'Draft'}
export default function AdvertisingPage(){const[camps,setCamps]=useState<any[]>([]),[stats,setStats]=useState<any>({}),[outlets,setOutlets]=useState<any[]>([]),[products,setProducts]=useState<any[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[saved,setSaved]=useState(''),[modal,setModal]=useState(false),[selected,setSelected]=useState<any>(null),[form,setForm]=useState<any>(blank),[saving,setSaving]=useState(false),[q,setQ]=useState('');
 const load=async()=>{setLoading(true);try{const[a,b,o,p]=await Promise.all([api('/api/vendor/advertising'),api('/api/vendor/advertising/stats'),api('/api/vendor/outlets'),api('/api/vendor/products')]);setCamps(a);setStats(b);setOutlets(o);setProducts(p)}catch(e:any){setError(e.message)}finally{setLoading(false)}};useEffect(()=>{load()},[]);const filtered=useMemo(()=>camps.filter(c=>!q||c.name.toLowerCase().includes(q.toLowerCase())),[camps,q]);const set=(k:string,v:any)=>setForm((f:any)=>({...f,[k]:v}));
 const openNew=()=>{const a=new Date(Date.now()+3600000),b=new Date(Date.now()+8*86400000);setSelected(null);setForm({...blank,startsAt:a.toISOString().slice(0,16),endsAt:b.toISOString().slice(0,16)});setModal(true)};const edit=(c:any)=>{setSelected(c);setForm({name:c.name,objective:c.objective,budget:(c.budgetAmount/100).toFixed(2),startsAt:new Date(c.startsAt).toISOString().slice(0,16),endsAt:new Date(c.endsAt).toISOString().slice(0,16),outletId:c.outletId||'',productIds:c.products.map((x:any)=>x.productId)});setModal(true)};
 async function save(){setSaving(true);setError('');try{const payload={name:form.name,objective:form.objective,budgetAmount:Math.round(Number(form.budget||0)*100),startsAt:new Date(form.startsAt).toISOString(),endsAt:new Date(form.endsAt).toISOString(),outletId:form.outletId||undefined,productIds:form.productIds};if(selected)await patch(`/api/vendor/advertising/${selected.id}`,payload);else await post('/api/vendor/advertising',payload);setModal(false);setSaved(selected?'Campaign updated':'Campaign created');load();setTimeout(()=>setSaved(''),2200)}catch(e:any){setError(e.message)}finally{setSaving(false)}}
 async function act(c:any,a:string){try{await post(`/api/vendor/advertising/${c.id}/${a}`);setSaved(a==='activate'?'Campaign activated':a==='pause'?'Campaign paused':'Campaign ended');load();setTimeout(()=>setSaved(''),2200)}catch(e:any){setError(e.message)}}
 return <VendorShell><div className="advertising-page"><div className="page-heading-row"><div><span className="eyebrow">Growth tools</span><h1>Advertising</h1><p className="page-subtitle">Promote your products, control campaign spend, and measure the sales your ads generate.</p></div><button className="btn" onClick={openNew}>＋ Create campaign</button></div>{error&&<div className="error">{error}</div>}{saved&&<div className="success">{saved}</div>}
 <div className="ad-metrics"><div><span>Campaigns</span><strong>{stats.campaigns||0}</strong></div><div><span>Active</span><strong>{stats.active||0}</strong></div><div><span>Spend</span><strong>{naira(stats.totalSpend)}</strong></div><div><span>Revenue</span><strong>{naira(stats.totalRevenue)}</strong></div><div><span>Impressions</span><strong>{(stats.impressions||0).toLocaleString()}</strong></div><div><span>ROAS</span><strong>{Number(stats.roas||0).toFixed(2)}×</strong></div></div>
 <div className="ad-performance"><div><div className="section-title"><div><span className="eyebrow">Performance</span><h2>Campaign health</h2></div><span className="performance-pill">CTR {Number(stats.ctr||0).toFixed(2)}%</span></div><div className="ad-bars"><div><span>Impressions</span><b>{(stats.impressions||0).toLocaleString()}</b></div><div><span>Clicks</span><b>{(stats.clicks||0).toLocaleString()}</b></div><div><span>Conversions</span><b>{(stats.conversions||0).toLocaleString()}</b></div></div></div><div className="ad-tip"><span>ROZZI tip</span><strong>Start with a focused product set</strong><p>Promoting a few strong products makes spend and conversion performance easier to understand.</p></div></div>
 <div className="ad-toolbar"><input className="input" placeholder="Search campaigns…" value={q} onChange={e=>setQ(e.target.value)}/><span>{filtered.length} campaign{filtered.length===1?'':'s'}</span></div>
 {loading?<div className="card ad-state">Loading advertising workspace…</div>:!filtered.length?<div className="card ad-state"><div className="state-icon">↗</div><h3>{q?'No campaigns found':'Create your first campaign'}</h3><p>{q?'Try another search.':'Put your products in front of more customers with a controlled campaign budget.'}</p>{!q&&<button className="btn" onClick={openNew}>Create campaign</button>}</div>:<div className="campaign-list">{filtered.map(c=><article className="campaign-card" key={c.id}><div className="campaign-head"><div><span className="campaign-objective">{c.objective}</span><h3>{c.name}</h3></div><span className={`status-badge ${state(c)==='Active'?'status-active':state(c)==='Scheduled'?'status-warning':'status-muted'}`}>{state(c)}</span></div><div className="campaign-numbers"><div><span>Budget</span><b>{naira(c.budgetAmount)}</b></div><div><span>Spend</span><b>{naira(c.spendAmount)}</b></div><div><span>Revenue</span><b>{naira(c.revenueAmount)}</b></div><div><span>Orders</span><b>{c.conversions}</b></div></div><div className="campaign-progress"><span style={{width:`${Math.min(100,(Number(c.spendAmount)/Math.max(1,Number(c.budgetAmount)))*100)}%`}}/></div><div className="campaign-meta"><span>{c.outlet?.name||'All outlets'}</span><span>{c.products.length?`${c.products.length} promoted product${c.products.length===1?'':'s'}`:'All vendor products'}</span><span>{new Date(c.startsAt).toLocaleDateString()} – {new Date(c.endsAt).toLocaleDateString()}</span></div><div className="campaign-actions"><button onClick={()=>edit(c)}>Edit</button>{state(c)==='Active'?<button onClick={()=>act(c,'pause')}>Pause</button>:state(c)!=='Ended'&&<button onClick={()=>act(c,'activate')}>Activate</button>}{state(c)!=='Ended'&&<button onClick={()=>act(c,'end')}>End</button>}</div></article>)}</div>}
 {modal&&<div className="modal-backdrop"><div className="modal ad-modal"><div className="modal-head"><div><span className="eyebrow">{selected?'Edit campaign':'New campaign'}</span><h2>{selected?'Update campaign':'Create advertising campaign'}</h2></div><button onClick={()=>setModal(false)}>×</button></div><div className="form-grid"><label>Campaign name<input className="input" value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Weekend product push"/></label><label>Objective<select className="input" value={form.objective} onChange={e=>set('objective',e.target.value)}><option value="ORDERS">Drive orders</option><option value="TRAFFIC">Drive traffic</option><option value="AWARENESS">Build awareness</option></select></label><label>Budget (₦)<input className="input" type="number" min="0" value={form.budget} onChange={e=>set('budget',e.target.value)} placeholder="50000"/></label><label>Outlet <span className="field-optional">optional</span><select className="input" value={form.outletId} onChange={e=>set('outletId',e.target.value)}><option value="">All outlets</option>{outlets.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select></label><label>Starts<input className="input" type="datetime-local" value={form.startsAt} onChange={e=>set('startsAt',e.target.value)}/></label><label>Ends<input className="input" type="datetime-local" value={form.endsAt} onChange={e=>set('endsAt',e.target.value)}/></label><label className="full-field">Promoted products <span className="field-optional">optional</span><select className="input" multiple size={6} value={form.productIds} onChange={e=>set('productIds',Array.from(e.target.selectedOptions).map((x:any)=>x.value))}>{products.map((p:any)=><option key={p.id} value={p.id}>{p.name}{p.sku?` · ${p.sku}`:''}</option>)}</select></label></div><div className="modal-note"><b>Advertising is different from Promotions</b><p>Promotions reduce the customer's order price. Advertising buys visibility for your products. Campaign spend and performance are tracked separately.</p></div><div className="modal-actions"><button className="btn secondary" onClick={()=>setModal(false)}>Cancel</button><button className="btn" disabled={saving||!form.name.trim()||!form.budget||!form.startsAt||!form.endsAt} onClick={save}>{saving?'Saving…':selected?'Save changes':'Create campaign'}</button></div></div></div>}</div></VendorShell>}
